 boolean isDock(int i){return i>=16&&i<20;}
 boolean isAppSlot(int i){return i>=0&&(i<20||i>=24&&i<=29||i==38||i==39);}
 int gridSlot(int cell){return cell<16?cell:cell<22?cell+8:cell+16;}
 int gridCell(int slot){return slot<=15?slot:slot<30?slot-8:slot-16;}
