 class FrostScroll extends ScrollView {Bitmap strip;Paint p=new Paint(3);FrostScroll(){super(Home.this);setClipToPadding(false);}public void draw(Canvas c){super.draw(c);int band=(screen==null?0:screen.bottomInset)+(int)dp(45),w=getWidth(),h=getScrollY()+getHeight();if(w<=0||getHeight()<=band)return;int bw=Math.max(1,w/10),bh=Math.max(1,band/10);if(strip==null||strip.getWidth()!=bw||strip.getHeight()!=bh)strip=Bitmap.createBitmap(bw,bh,Bitmap.Config.ARGB_8888);strip.eraseColor(Color.TRANSPARENT);Canvas tiny=new Canvas(strip);tiny.scale(.1f,.1f);tiny.translate(0,-(h-band));super.draw(tiny);RectF area=new RectF(0,h-band,w,h);int save=c.saveLayer(area,null);p.setShader(null);p.setXfermode(null);c.drawBitmap(strip,null,area,p);p.setShader(new LinearGradient(0,h-band,0,h,new int[]{0x00ffffff,0xffffffff},null,Shader.TileMode.CLAMP));p.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.DST_IN));c.drawRect(area,p);p.setXfermode(null);p.setShader(null);c.restoreToCount(save);p.setShader(new LinearGradient(0,h-band,0,h,new int[]{0x0009162b,0x6609162b},null,Shader.TileMode.CLAMP));c.drawRect(area,p);p.setShader(null);}}

